import unittest

from minigpt.clean import clean_text, describe


class CleanTests(unittest.TestCase):
    def test_cleaning_twice_changes_nothing(self):
        raw = "To be,  or not to be.\r\n\r\n\r\nThat is the question.  \n"
        once = clean_text(raw)
        self.assertEqual(clean_text(once), once)

    def test_smart_quotes_and_spaces_are_normalised(self):
        self.assertEqual(clean_text("“Hi”   there"), '"Hi" there\n')

    def test_describe_counts(self):
        info = describe("aab\n")
        self.assertEqual(info["n_chars"], 4)
        self.assertEqual(info["vocab_size"], 3)
        self.assertEqual(info["most_common"][0], ("a", 2))


if __name__ == "__main__":
    unittest.main()

"""Character-level tokenizer: text <-> list[int]."""
from __future__ import annotations

import json
from pathlib import Path

class CharTokenizer:
    def __init__(self, chars: list[str]):
        if len(set(chars)) != len(chars):
            raise ValueError("vocabulary contains duplicate characters")
        self.chars = list(chars)
        self.stoi = {ch: i for i, ch in enumerate(self.chars)}
        self.itos = {i: ch for i, ch in enumerate(self.chars)}

    @classmethod
    def from_text(cls, text: str) -> "CharTokenizer":
        return cls(sorted(set(text)))

    @property
    def vocab_size(self) -> int:
        return len(self.chars)

    def encode(self, text: str) -> list[int]:
        try:
            return [self.stoi[ch] for ch in text]
        except KeyError as e:
            raise ValueError(f"character {e.args[0]!r} not in vocabulary") from None

    def decode(self, ids) -> str:
        return "".join(self.itos[int(i)] for i in ids)

    def save(self, path) -> None:
        Path(path).write_text(json.dumps({"chars": self.chars}), encoding="utf-8")

    @classmethod
    def load(cls, path) -> "CharTokenizer":
        return cls(json.loads(Path(path).read_text(encoding="utf-8"))["chars"])

import tempfile
import unittest
from pathlib import Path

from minigpt.tokenizer import CharTokenizer

TEXT = "To be, or not to be.\n"


class TokenizerTests(unittest.TestCase):
    def setUp(self):
        self.tok = CharTokenizer.from_text(TEXT)

    def test_roundtrip_is_lossless(self):
        self.assertEqual(self.tok.decode(self.tok.encode(TEXT)), TEXT)

    def test_vocab_size_matches_unique_chars(self):
        self.assertEqual(self.tok.vocab_size, len(set(TEXT)))

    def test_ids_are_in_range(self):
        ids = self.tok.encode(TEXT)
        self.assertTrue(all(0 <= i < self.tok.vocab_size for i in ids))

    def test_unknown_character_raises(self):
        with self.assertRaises(ValueError):
            CharTokenizer.from_text("abc").encode("z")

    def test_save_and_load(self):
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / "vocab.json"
            self.tok.save(path)
            self.assertEqual(CharTokenizer.load(path).encode(TEXT), self.tok.encode(TEXT))


if __name__ == "__main__":
    unittest.main()

"""Count-based bigram model. The number the transformer has to beat."""
from __future__ import annotations

import numpy as np

class CountBigram:
    def __init__(self, vocab_size: int, alpha: float = 1.0):
        self.vocab_size = vocab_size
        self.alpha = alpha                       # add-alpha smoothing
        self.counts = np.zeros((vocab_size, vocab_size), dtype=np.float64)

    def fit(self, ids) -> "CountBigram":
        ids = np.asarray(ids)
        np.add.at(self.counts, (ids[:-1], ids[1:]), 1.0)
        return self

    @property
    def probs(self) -> np.ndarray:
        smoothed = self.counts + self.alpha
        return smoothed / smoothed.sum(axis=1, keepdims=True)

    def nll(self, ids) -> float:
        """Mean negative log likelihood in nats - same units as cross_entropy."""
        ids = np.asarray(ids)
        p = self.probs[ids[:-1], ids[1:]]
        return float(-np.log(p).mean())

    def generate(self, n: int, start: int = 0, seed: int = 0) -> list[int]:
        rng = np.random.default_rng(seed)
        probs, out, cur = self.probs, [start], start
        for _ in range(n):
            cur = int(rng.choice(self.vocab_size, p=probs[cur]))
            out.append(cur)
        return out

from __future__ import annotations

from dataclasses import asdict, dataclass

import torch
import yaml

def get_device() -> str:
    if torch.cuda.is_available():
        return "cuda"
    if torch.backends.mps.is_available():
        return "mps"
    return "cpu"

@dataclass
class Config:
    # model
    vocab_size: int = 65
    block_size: int = 256
    n_layer: int = 6
    n_head: int = 6
    n_embd: int = 384
    dropout: float = 0.2
    # optimisation
    batch_size: int = 64
    learning_rate: float = 3e-4
    max_iters: int = 5000
    eval_interval: int = 250
    eval_iters: int = 200
    # housekeeping
    seed: int = 1337
    device: str = ""

    def __post_init__(self):
        if self.n_embd % self.n_head != 0:
            raise ValueError("n_embd must be divisible by n_head")
        if not self.device:
            self.device = get_device()

    @classmethod
    def from_yaml(cls, path) -> "Config":
        with open(path) as f:
            return cls(**(yaml.safe_load(f) or {}))

    def to_dict(self) -> dict:
        return asdict(self)

from __future__ import annotations

import torch
import torch.nn as nn
from torch.nn import functional as F

class Head(nn.Module):
    """One head of causal self-attention."""

    def __init__(self, cfg, head_size):
        super().__init__()
        self.key = nn.Linear(cfg.n_embd, head_size, bias=False)
        self.query = nn.Linear(cfg.n_embd, head_size, bias=False)
        self.value = nn.Linear(cfg.n_embd, head_size, bias=False)
        self.register_buffer(
            "tril", torch.tril(torch.ones(cfg.block_size, cfg.block_size)))
        self.dropout = nn.Dropout(cfg.dropout)

    def forward(self, x):
        B, T, C = x.shape
        k, q, v = self.key(x), self.query(x), self.value(x)
        att = q @ k.transpose(-2, -1) * k.shape[-1] ** -0.5   # (B,T,T)
        att = att.masked_fill(self.tril[:T, :T] == 0, float("-inf"))
        att = self.dropout(F.softmax(att, dim=-1))
        return att @ v

class MultiHeadAttention(nn.Module):
    def __init__(self, cfg):
        super().__init__()
        head_size = cfg.n_embd // cfg.n_head
        self.heads = nn.ModuleList(
            [Head(cfg, head_size) for _ in range(cfg.n_head)])
        self.proj = nn.Linear(cfg.n_embd, cfg.n_embd)
        self.dropout = nn.Dropout(cfg.dropout)

    def forward(self, x):
        out = torch.cat([h(x) for h in self.heads], dim=-1)
        return self.dropout(self.proj(out))

class FeedForward(nn.Module):
    def __init__(self, cfg):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(cfg.n_embd, 4 * cfg.n_embd),
            nn.GELU(),
            nn.Linear(4 * cfg.n_embd, cfg.n_embd),
            nn.Dropout(cfg.dropout),
        )

    def forward(self, x):
        return self.net(x)

class Block(nn.Module):
    """Pre-norm transformer block: normalise, transform, add back."""

    def __init__(self, cfg):
        super().__init__()
        self.ln1, self.ln2 = nn.LayerNorm(cfg.n_embd), nn.LayerNorm(cfg.n_embd)
        self.attn, self.ff = MultiHeadAttention(cfg), FeedForward(cfg)

    def forward(self, x):
        x = x + self.attn(self.ln1(x))
        x = x + self.ff(self.ln2(x))
        return x

class GPT(nn.Module):
    def __init__(self, cfg):
        super().__init__()
        self.cfg = cfg
        self.tok_emb = nn.Embedding(cfg.vocab_size, cfg.n_embd)
        self.pos_emb = nn.Embedding(cfg.block_size, cfg.n_embd)
        self.drop = nn.Dropout(cfg.dropout)
        self.blocks = nn.Sequential(*[Block(cfg) for _ in range(cfg.n_layer)])
        self.ln_f = nn.LayerNorm(cfg.n_embd)
        self.head = nn.Linear(cfg.n_embd, cfg.vocab_size)
        self.apply(self._init_weights)

    @staticmethod
    def _init_weights(module):
        if isinstance(module, nn.Linear):
            nn.init.normal_(module.weight, mean=0.0, std=0.02)
            if module.bias is not None:
                nn.init.zeros_(module.bias)
        elif isinstance(module, nn.Embedding):
            nn.init.normal_(module.weight, mean=0.0, std=0.02)

    def n_params(self) -> int:
        return sum(p.numel() for p in self.parameters())

    def forward(self, idx, targets=None):
        B, T = idx.shape
        if T > self.cfg.block_size:
            raise ValueError(f"sequence of {T} exceeds block_size {self.cfg.block_size}")
        pos = torch.arange(T, device=idx.device)
        x = self.drop(self.tok_emb(idx) + self.pos_emb(pos))
        x = self.ln_f(self.blocks(x))
        logits = self.head(x)                                 # (B,T,vocab)

        loss = None
        if targets is not None:
            loss = F.cross_entropy(logits.view(B * T, -1), targets.reshape(B * T))
        return logits, loss

    @torch.no_grad()
    def generate(self, idx, max_new_tokens, temperature=1.0, top_k=None):
        self.eval()
        for _ in range(max_new_tokens):
            idx_cond = idx[:, -self.cfg.block_size:]
            logits, _ = self(idx_cond)
            logits = logits[:, -1, :] / temperature
            if top_k is not None:
                v, _ = torch.topk(logits, min(top_k, logits.size(-1)))
                logits[logits < v[:, [-1]]] = -float("inf")
            probs = F.softmax(logits, dim=-1)
            idx = torch.cat((idx, torch.multinomial(probs, 1)), dim=1)
        return idx
